
-- Extend the existing Expo push outbox to deliver non-offer notifications,
-- including subscription-based taxi high-demand alerts.
ALTER TABLE public.push_delivery_outbox ALTER COLUMN offer_id DROP NOT NULL;
ALTER TABLE public.push_delivery_outbox ALTER COLUMN request_id DROP NOT NULL;
ALTER TABLE public.push_delivery_outbox ADD COLUMN IF NOT EXISTS notification_id uuid REFERENCES public.notifications(id) ON DELETE CASCADE;
CREATE UNIQUE INDEX IF NOT EXISTS push_delivery_outbox_notification_token_uidx
 ON public.push_delivery_outbox(notification_id,expo_push_token) WHERE notification_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.process_mamnoon_push_outbox() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'net', 'pg_temp' AS $function$ declare r record; v_response record; v_content jsonb; v_ticket jsonb; v_receipt jsonb; v_request_id bigint; v_processed integer := 0; v_error text; begin -- Resolve asynchronous send responses and retry transient failures.
for r in select * from public.push_delivery_outbox where status = 'sending' and http_request_id is not null order by submitted_at for update skip locked limit 100 loop select * into v_response from net._http_response where id = r.http_request_id; if not found then if r.submitted_at < now() - interval '3 minutes' then if r.attempts >= 6 then update public.push_delivery_outbox set status = 'failed', last_error = 'No response from Expo after retries', updated_at = now() where id = r.id; else update public.push_delivery_outbox set status = 'queued', next_attempt_at = now() + make_interval(secs => least(300, 15 * power(2, greatest(r.attempts - 1, 0))::integer)), http_request_id = null, submitted_at = null, last_error = 'Expo request timed out; retry scheduled', updated_at = now() where id = r.id; end if; end if; continue; end if; v_content := null; begin v_content := v_response.content::jsonb; exception when others then v_content := '{}'::jsonb; end; v_ticket := v_content #> '{data,0}'; if v_response.status_code between 200 and 299 and v_ticket->>'status' = 'ok' and nullif(v_ticket->>'id', '') is not null then update public.push_delivery_outbox set status = 'accepted', expo_ticket_id = v_ticket->>'id', sent_at = now(), next_attempt_at = now() + interval '15 minutes', http_request_id = null, submitted_at = null, last_error = null, updated_at = now() where id = r.id; else v_error := coalesce( v_ticket->>'message', v_ticket #>> '{details,error}', v_response.error_msg, 'Expo rejected the push request' ); if v_ticket #>> '{details,error}' = 'DeviceNotRegistered' then delete from public.user_push_tokens where user_id = r.provider_id and expo_push_token = r.expo_push_token; update public.push_delivery_outbox set status = 'failed', last_error = v_error, http_request_id = null, submitted_at = null, updated_at = now() where id = r.id; elsif r.attempts >= 6 then update public.push_delivery_outbox set status = 'failed', last_error = left(v_error, 500), http_request_id = null, submitted_at = null, updated_at = now() where id = r.id; else update public.push_delivery_outbox set status = 'queued', next_attempt_at = now() + make_interval(secs => least(300, 15 * power(2, greatest(r.attempts - 1, 0))::integer)), http_request_id = null, submitted_at = null, last_error = left(v_error, 500), updated_at = now() where id = r.id; end if; end if; v_processed := v_processed + 1; end loop; -- Check Expo delivery receipts after the provider has had time to process them.
for r in select * from public.push_delivery_outbox where status = 'receipt_pending' and receipt_request_id is not null order by receipt_requested_at for update skip locked limit 100 loop select * into v_response from net._http_response where id = r.receipt_request_id; if not found then if r.receipt_requested_at < now() - interval '5 minutes' then update public.push_delivery_outbox set status = 'accepted', receipt_request_id = null, receipt_requested_at = null, next_attempt_at = now() + interval '5 minutes', last_error = 'Receipt response delayed; will check again', updated_at = now() where id = r.id; end if; continue; end if; v_content := null; begin v_content := v_response.content::jsonb; exception when others then v_content := '{}'::jsonb; end; v_receipt := v_content #> array['data', r.expo_ticket_id]; if v_response.status_code between 200 and 299 and v_receipt->>'status' = 'ok' then update public.push_delivery_outbox set status = 'delivered', delivered_at = now(), receipt_request_id = null, receipt_requested_at = null, last_error = null, updated_at = now() where id = r.id; elsif v_receipt #>> '{details,error}' = 'DeviceNotRegistered' then delete from public.user_push_tokens where user_id = r.provider_id and expo_push_token = r.expo_push_token; update public.push_delivery_outbox set status = 'failed', last_error = coalesce(v_receipt->>'message', 'DeviceNotRegistered'), receipt_request_id = null, receipt_requested_at = null, updated_at = now() where id = r.id; else update public.push_delivery_outbox set status = 'accepted', receipt_request_id = null, receipt_requested_at = null, next_attempt_at = now() + interval '5 minutes', last_error = left(coalesce(v_receipt->>'message', v_response.error_msg, 'Delivery receipt not available yet'), 500), updated_at = now() where id = r.id; end if; v_processed := v_processed + 1; end loop; -- Request receipts for accepted tickets. Expo receipts are not available immediately.
for r in select * from public.push_delivery_outbox where status = 'accepted' and expo_ticket_id is not null and next_attempt_at <= now() and receipt_request_id is null order by sent_at for update skip locked limit 100 loop v_request_id := net.http_post( url := 'https://exp.host/--/api/v2/push/getReceipts', body := jsonb_build_object('ids', jsonb_build_array(r.expo_ticket_id)), headers := '{"Content-Type":"application/json","Accept":"application/json"}'::jsonb, timeout_milliseconds := 5000 ); update public.push_delivery_outbox set status = 'receipt_pending', receipt_request_id = v_request_id, receipt_requested_at = now(), updated_at = now() where id = r.id; v_processed := v_processed + 1; end loop; -- Expired or already-claimed offers must never produce a late push.
update public.push_delivery_outbox o set status = 'failed', last_error = 'Offer is no longer active', updated_at = now() from public.request_offers ro join public.service_requests sr on sr.id = ro.request_id where o.offer_id = ro.id and o.request_id = sr.id and o.offer_id IS NOT NULL and o.status = 'queued' and (ro.status <> 'pending' or ro.expires_at <= now() or sr.status not in ('pending', 'searching') or sr.provider_id is not null); -- Submit due notifications in bounded batches; each message has its own retry state.
for r in select o.* from public.push_delivery_outbox o left join public.request_offers ro on ro.id = o.offer_id left join public.service_requests sr on sr.id = o.request_id left join public.notifications n on n.id = o.notification_id where o.status = 'queued' and o.next_attempt_at <= now() and o.attempts < 6 and ( (o.offer_id IS NOT NULL AND ro.status = 'pending' AND ro.expires_at > now() AND sr.status in ('pending', 'searching') AND sr.provider_id is null) OR (o.notification_id IS NOT NULL AND n.id IS NOT NULL) ) order by o.created_at for update of o skip locked limit 100 loop v_request_id := net.http_post( url := 'https://exp.host/--/api/v2/push/send', body := r.payload, headers := '{"Content-Type":"application/json","Accept":"application/json"}'::jsonb, timeout_milliseconds := 5000 ); update public.push_delivery_outbox set status = 'sending', attempts = attempts + 1, http_request_id = v_request_id, submitted_at = now(), last_error = null, updated_at = now() where id = r.id; v_processed := v_processed + 1; end loop; update public.push_delivery_outbox set status = 'failed', last_error = coalesce(last_error, 'Retry limit reached'), updated_at = now() where status = 'queued' and attempts >= 6; return v_processed; end; $function$;

CREATE OR REPLACE FUNCTION public.enqueue_notification_push() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $function$ BEGIN IF NEW.type='request_offer' THEN RETURN NEW; END IF; INSERT INTO public.push_delivery_outbox(notification_id,request_id,provider_id,expo_push_token,payload) SELECT NEW.id, CASE WHEN (NEW.data->>'request_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (NEW.data->>'request_id')::uuid ELSE NULL END, NEW.user_id,t.expo_push_token, jsonb_build_object('to',t.expo_push_token,'title',NEW.title,'body',NEW.body,'sound','default','priority',CASE WHEN NEW.data->>'plan'='gold' THEN 'high' ELSE 'normal' END,'channelId','default', 'data',jsonb_build_object('type',NEW.type,'notification_id',NEW.id,'request_id',NEW.data->>'request_id','url',COALESCE(NEW.link,'/profile'))) FROM public.user_push_tokens t WHERE t.user_id=NEW.user_id AND (t.expo_push_token LIKE 'ExpoPushToken[%' OR t.expo_push_token LIKE 'ExponentPushToken[%') ON CONFLICT (notification_id,expo_push_token) WHERE notification_id IS NOT NULL DO NOTHING; PERFORM public.process_mamnoon_push_outbox(); RETURN NEW; END; $function$;
REVOKE ALL ON FUNCTION public.process_mamnoon_push_outbox() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.enqueue_notification_push() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS trg_enqueue_notification_push ON public.notifications;
CREATE TRIGGER trg_enqueue_notification_push AFTER INSERT ON public.notifications
FOR EACH ROW EXECUTE FUNCTION public.enqueue_notification_push();
